export function basicCalculatorIi(expression        )         {
const s=expression.replace(/ /g,'');const stack         =[];let number=0,op='+';for(let i=0;i<=s.length;i++){const c=s[i];if(c!==undefined&&/\d/.test(c)){number=number*10+Number(c);continue;}if(op==='+')stack.push(number);if(op==='-')stack.push(-number);if(op==='*')stack.push(stack.pop() *number);if(op==='/')stack.push(Math.trunc(stack.pop() /number));op=c;number=0;}return stack.reduce((a,b)=>a+b,0);
}

